
export function bandera(country) {
    if(country.includes("France")){
        return "triangleFrancia"
    }else if (country.includes("Switzerland")){
        return "triangleSwitzerland"
    }else if (country.includes("Morocco")){
        return "triangleMarruecos"
    }else if (country.includes("Austria")){
        return "triangleAustria"
    }else if (country.includes("Brazil")){
        return "triangleBrasil"
    }else if (country.includes("Italy")){
        return "triangleItalia"
    }else if (country.includes("Bulgaria")){
        return "triangleBulgaria"
    }else if (country.includes("macedonia")){
        return "triangleMacedonia"
    }else if (country.includes("Japan")){
        return "triangleJapon"
    }else if (country.includes("Mexico")){
        return "triangleMexico"
    }else if (country.includes("Ethiopia")){
        return "triangleEthiopia"
    }else if (country.includes("Serbia")){
        return "triangleSerbia"
    }else if (country.includes("Romania")){
        return "triangleRomania"
    }else if (country.includes("Spain")){
        return "triangleEspania"
    }else if (country.includes("Slovenia")){
        return "triangleEslovenia"
    }else if (country.includes("Usa")){
        return "triangleUsa"
    }else if (country.includes("Turkey")){
        return "triangleTurkia"
    }else if (country.includes("korea")){
        return "triangleKorea"
    }else if (country.includes("Tunisia")){
        return "triangleTunisia"
    }else if (country.includes("Czech")){
        return "triangleCheca"
    }else if (country.includes("Bosnia")){
        return "triangleBosnia"
    }
}
    